<script setup lang="ts">
import {useTableWidths} from './tableWidths'
const tableWidths=useTableWidths('AdvertisingPanel')

import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {Search,Refresh,ArrowRight,EditPen,Check} from '@element-plus/icons-vue'
import {api,session,can} from './session'
import AdsCreatePage from './AdsCreatePage.vue'
const props=defineProps<{focus?:{store:string,marketplace:string,asin:string,request:number}|null,context?:any}>()
const emit=defineEmits(['open-entity','home'])
const section=ref(props.context?.group?'ad':props.context?'adgroup':'campaign')
const levelFor=(key:string)=>['auto','keyword','product'].includes(key)?'target':['negative_keyword','negative_product'].includes(key)?'negative':['placement','strategy','settings'].includes(key)?'campaign':key
const rootSections=[['campaign','广告活动'],['placement','广告位'],['adgroup','广告组'],['ad','广告'],['auto','自动投放'],['keyword','关键词'],['product','商品投放'],['negative_keyword','否定词'],['negative_product','否定投放'],['search','用户搜索词']]
const entitySections=[['campaign','广告活动'],['adgroup','广告组'],['ad','广告'],['placement','广告位'],['target','投放'],['negative','否定投放'],['search','用户搜索词'],['strategy','广告策略'],['logs','操作日志'],['settings','广告活动设置']]
const sections=computed(()=>(props.context?entitySections:rootSections).filter(([key])=>['campaign','adgroup'].includes(levelFor(key))?can('advertising'):can('advertising.'+levelFor(key))))
function selectSection(key:string){section.value=key;sort.value='';inlineValues.value={};search()}

const createMode=ref('')
const canEditAds=computed(()=>can(['campaign','adgroup'].includes(currentLevel.value)?'advertising':'advertising.'+currentLevel.value,'operate'))
const profiles=ref<any[]>([]),profile=ref(''),country=ref('UK'),store=ref(''),campaign=ref<any>(props.context?.campaign||null),group=ref<any>(props.context?.group||null)
const dates=ref<string[]>([]),preset=ref('7'),q=ref(''),searchType=ref('all'),state=ref(''),page=ref(1),pageSize=ref(25),loading=ref(false),syncing=ref(false),error=ref(''),data=ref<any>({rows:[],total:0}),jobs=ref<any[]>([]),showJobs=ref(false),sort=ref(''),direction=ref('desc'),hover=ref<number|null>(null)
const editOpen=ref(false),editBusy=ref(false),editRow=ref<any>(null),isCreate=ref(false),editKind=ref(''),editForm=ref<any>({}),previewData=ref<any>(null),editError=ref('')
const suggestLoading=ref(false)
const labels:Record<string,string>={campaign:'广告活动',adgroup:'广告组',ad:'广告',target:'投放',negative:'否定投放',search:'用户搜索词',logs:'操作日志'}
const states:Record<string,string>={ENABLED:'已开启',PAUSED:'已暂停',ARCHIVED:'已归档',UNKNOWN:'未知'}
const statusNames:Record<string,string>={preview:'待确认',sending:'提交中／待核对',succeeded:'成功',failed:'失败',unknown:'结果待核对'}
const fieldNames:Record<string,string>={state:'状态',bid:'竞价',defaultBid:'默认竞价',name:'名称',dailyBudget:'每日预算',portfolioId:'广告组合',endDate:'结束日期',biddingStrategy:'竞价策略',placementTop:'首页首位加价',placementRest:'搜索其余位置加价',placementProduct:'商品页面加价',placementBusiness:'亚马逊企业购加价',audiences:'受众加价',offAmazonStrategy:'站外投放设置',note:'备注（仅本地）',keywordText:'否定关键词',matchType:'否定方式',asin:'否定商品ASIN'}
const matchNames:Record<string,string>={BROAD:'广泛匹配',PHRASE:'词组匹配',EXACT:'精准匹配',AUTO:'自动投放',MANUAL:'商品投放',NEGATIVE_EXACT:'否定精准',NEGATIVE_PHRASE:'否定词组'}
const periodOptions=[['today','今天'],['yesterday','昨天'],['3','最近3天'],['7','最近7天'],['14','最近14天'],['30','最近30天'],['m3','最近三个月'],['m6','最近半年'],['y1','最近一年'],['custom','自定义']]
const jobStates:Record<string,string>={queued:'排队中',running:'同步中',waiting:'等待亚马逊生成报表',succeeded:'已完成',failed:'部分或全部失败'}
const currentLevel=computed(()=>levelFor(section.value))
const entityFilter=computed(()=>['auto','keyword','product','negative_keyword','negative_product'].includes(section.value)?section.value:'')
const specialView=computed(()=>['placement','strategy','settings'].includes(section.value))
const countryNames:Record<string,string>={FR:'法国',UK:'英国',DE:'德国',IT:'意大利',ES:'西班牙',NL:'荷兰',BE:'比利时',IE:'爱尔兰',SE:'瑞典',PL:'波兰',AE:'阿联酋',SA:'沙特'}
const countries=computed(()=>[...new Set(profiles.value.filter(p=>p.account===store.value).map(p=>p.country==='GB'?'UK':p.country))])
const stores=computed(()=>[...new Set(profiles.value.map(p=>p.account))])
const active=computed(()=>jobs.value.some(j=>['queued','running','waiting'].includes(j.status)))
const performanceCurrency=ref('')
const currency=computed(()=>data.value.currencies?.includes(performanceCurrency.value)?performanceCurrency.value:data.value.currency||data.value.currencies?.[0]||profiles.value.find(p=>p.id===profile.value)?.currency||'EUR')
const summary=computed(()=>data.value.summaries?.[currency.value]??data.value.summary)
const editCurrency=computed(()=>editRow.value?.currency||currency.value)
const money=(v:any,code=currency.value)=>v==null?'—':new Intl.NumberFormat('zh-CN',{style:'currency',currency:code}).format(Number(v))
const number=(v:any)=>v==null?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:0})
const percent=(v:any)=>v==null?'—':Number(v).toFixed(2)+'%'
const time=(v:any)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'未同步'
const fieldValue=(key:string,v:any)=>v==null?'未设置':['bid','defaultBid','dailyBudget'].includes(key)?money(v,editCurrency.value):key==='state'?(states[v]||v):key==='matchType'?(matchNames[v]||v):typeof v==='object'?JSON.stringify(v):String(v)
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:profiles.value.find(p=>p.id===profile.value)?.timezone||'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const iso=(d:Date)=>d.toISOString().slice(0,10)
function periodDates(value:string){const end=new Date(today()+'T12:00:00Z'),start=new Date(end);if(value==='yesterday'){start.setUTCDate(start.getUTCDate()-1);end.setUTCDate(end.getUTCDate()-1)}else if(['3','7','14','30'].includes(value))start.setUTCDate(start.getUTCDate()-Number(value)+1);else if(['m3','m6','y1'].includes(value)){const day=start.getUTCDate();start.setUTCDate(1);start.setUTCMonth(start.getUTCMonth()-(value==='m3'?3:value==='m6'?6:12));const last=new Date(Date.UTC(start.getUTCFullYear(),start.getUTCMonth()+1,0)).getUTCDate();start.setUTCDate(Math.min(day,last));start.setUTCDate(start.getUTCDate()+1)}return [iso(start),iso(end)]}
function choosePeriod(){if(preset.value!=='custom'){dates.value=periodDates(preset.value);search()}}
const shortcuts=periodOptions.filter(p=>p[0]!=='custom').map(p=>({text:p[1],value:()=>periodDates(p[0]).map(v=>new Date(v+'T12:00:00'))}))
let loadedLevel='',request=0,timer:ReturnType<typeof setInterval>|undefined
async function load(){
 if(!store.value||dates.value?.length!==2)return
 const id=++request;loading.value=true;error.value='';hover.value=null
 if(loadedLevel!==currentLevel.value){data.value={rows:[],total:0};loadedLevel=currentLevel.value}
 try{const p=new URLSearchParams({profile_id:profile.value,level:currentLevel.value,campaign_id:campaign.value?.id||'',adgroup_id:currentLevel.value==='campaign'?'':group.value?.id||'',start:dates.value[0],end:dates.value[1],q:q.value,search_type:searchType.value,state:currentLevel.value==='logs'||currentLevel.value==='search'?'':state.value,page:String(page.value),page_size:String(pageSize.value),sort:sort.value,direction:direction.value,entity_filter:entityFilter.value});if(!props.context){p.delete('profile_id');p.set('store',store.value);p.set('country',country.value)}const r=await api((props.context?'/advertising/workspace?':'/advertising/workspace-overview?')+p);if(id===request)data.value=r}catch(e){if(id===request)error.value=(e as Error).message}finally{if(id===request)loading.value=false}
}
async function loadJobs(){const pid=profile.value;if(pid){const result=await api('/advertising/jobs?'+new URLSearchParams({profile_id:pid}));if(profile.value===pid)jobs.value=result}}
function search(){page.value=1;load()}
function openEntity(kind:string,row:any,parent:any=null){
 const pid=row.profile_id||profile.value,p=profiles.value.find(p=>p.id===pid)
 const brief=(r:any)=>r?{id:r.id,name:r.name,state:r.state,default_bid:r.default_bid,profile_id:pid,currency:r.currency||p?.currency}:null
 emit('open-entity',{profileId:pid,store:p?.account||store.value,country:p?.country||country.value,campaign:brief(kind==='campaign'?row:parent),group:kind==='adgroup'?brief(row):null})
}
function drill(row:any){if(currentLevel.value==='campaign')openEntity('campaign',row);else if(currentLevel.value==='adgroup')openEntity('adgroup',row,campaign.value||{id:row.campaign_id,name:row.campaign_name})}
function openFocusedAsin(){
 if(props.context)return
 const f=props.focus;if(!f||!profiles.value.length)return
 store.value=f.store;country.value=f.marketplace==='GB'?'UK':f.marketplace;section.value='adgroup';q.value=f.asin;searchType.value='asin';accountChange()
}
watch(()=>props.focus,openFocusedAsin)
async function accountChange(){
 jobs.value=[];preferences.value={};widths.value={};profile.value=profiles.value.find(p=>p.account===store.value&&(!country.value||(p.country==='GB'?'UK':p.country)===country.value))?.id||''
 data.value={rows:[],total:0};inlineValues.value={};search();await Promise.all([loadJobs(),loadPreferences()])
}
async function sync(){if(dates.value?.length!==2)return;syncing.value=true;try{const r=await api('/advertising/sync',{profile_id:profile.value,start:dates.value[0],end:dates.value[1]});ElMessage.success(r.created?'同步已排队，按天保存表现数据':'已有同步任务，请等待完成');await loadJobs()}catch(e){ElMessage.error((e as Error).message)}finally{syncing.value=false}}
function startEdit(row:any){quickField.value='';campaignSettings.value=null;editRow.value=row;editKind.value=row.kind;isCreate.value=false;editForm.value={state:row.state,bid:row.bid,defaultBid:row.default_bid,name:row.name};previewData.value=null;editError.value='';editOpen.value=true}
function startNegative(row?:any){if(!row&&!group.value){ElMessage.warning('请先进入一个广告组，再新增否定投放');return}editRow.value=row||group.value;isCreate.value=true;editKind.value=/^[A-Z0-9]{10}$/i.test(row?.name||'')?'negative_target':'negative_keyword';editForm.value={keywordText:row?.name||'',matchType:'NEGATIVE_EXACT',asin:editKind.value==='negative_target'?row.name.toUpperCase():''};previewData.value=null;editError.value='';editOpen.value=true}
async function preview(){editBusy.value=true;editError.value='';try{let changes:any={};if(isCreate.value)changes=editKind.value==='negative_keyword'?{keywordText:editForm.value.keywordText,matchType:editForm.value.matchType}:{asin:editForm.value.asin?.trim().toUpperCase()};else{const old=editRow.value;const values:any=editKind.value==='campaign'?campaignBaseline.value:{state:old.state,bid:old.bid,defaultBid:old.default_bid,name:old.name};const keys=editKind.value==='campaign'?Object.keys(editForm.value):editKind.value==='adgroup'?['state','defaultBid','name']:['keyword','target'].includes(editKind.value)?['state','bid']:['state'];for(const key of keys){const val=editForm.value[key];const different=['bid','defaultBid','dailyBudget'].includes(key)?Math.round(Number(val)*100)!==Math.round(Number(values[key])*100):JSON.stringify(val)!==JSON.stringify(values[key]);if(different)changes[key]=val}if(!Object.keys(changes).length){ElMessage.info('没有修改内容');return}}previewData.value=await api('/advertising/edit/preview',{profile_id:editRow.value?.profile_id||profile.value,kind:editKind.value,entity_id:isCreate.value?'':editRow.value.id,adgroup_id:isCreate.value?(editRow.value.adgroup_id||editRow.value.id):'',changes,create:isCreate.value})}catch(e){editError.value=(e as Error).message}finally{editBusy.value=false}}
async function confirm(){if(!previewData.value)return;editBusy.value=true;editError.value='';try{const changed={...previewData.value.changes};const r=await api('/advertising/edit/confirm',{id:previewData.value.id});previewData.value=null;if(r.status==='succeeded'){if(editKind.value==='adgroup'&&group.value?.id===editRow.value.id)group.value={...group.value,...changed,default_bid:changed.defaultBid??group.value.default_bid};ElMessage.success(r.message);editOpen.value=false;delete inlineValues.value[editRow.value.key];await load()}else{editError.value=r.message;await load()}}catch(e){editError.value=(e as Error).message;previewData.value=null}finally{editBusy.value=false}}
async function refreshSuggestions(){
 const batches=new Map<string,Set<string>>();for(const r of data.value.rows){if(!r.adgroup_id)continue;const pid=r.profile_id||profile.value;if(!batches.has(pid))batches.set(pid,new Set());batches.get(pid)!.add(r.adgroup_id)}
 suggestLoading.value=true;try{const errors:string[]=[];for(const [pid,ids] of batches){const r=await api('/advertising/target-suggestions/refresh',{profile_id:pid,group_ids:[...ids]});errors.push(...r.errors.map((e:any)=>e.message))}await load();if(errors.length)ElMessage.warning(errors.join('；'));else ElMessage.success('建议竞价已更新')}catch(e){ElMessage.error((e as Error).message)}finally{suggestLoading.value=false}
}
function applySuggestion(row:any,key:string){const value=row.suggestion?.[key];if(value!=null){changeInline(row,'bid',value);ElMessage.success('已填入竞价框，点击保存后确认提交')}}
onMounted(async()=>{try{const r=await api('/advertising/profiles');profiles.value=r.profiles;store.value=props.context?.store||session.value?.default_store||session.value?.current_store||r.profiles[0]?.account||'';country.value=props.context?.country||'UK';if(country.value==='GB')country.value='UK';profile.value=props.context?.profileId||r.profiles.find((p:any)=>p.account===store.value&&(p.country==='UK'||p.country==='GB'))?.id||'';if(!sections.value.some(([k])=>k===section.value))section.value=sections.value[0]?.[0]||'campaign';dates.value=periodDates('7');await Promise.all([load(),loadJobs(),loadPreferences()]);openFocusedAsin();timer=setInterval(async()=>{try{if(!active.value||document.hidden)return;await loadJobs();if(!active.value)await load()}catch{}},15000)}catch(e){error.value=(e as Error).message}})
onUnmounted(()=>{if(timer)clearInterval(timer);request++})
const metricColumns=[{key:'impressions',label:'曝光',type:'number'},{key:'clicks',label:'点击量',type:'number'},{key:'ctr',label:'点击率',type:'percent'},{key:'cost',label:'总成本',type:'money'},{key:'cpc',label:'CPC',type:'money'},{key:'purchases',label:'购买量',type:'number'},{key:'sales',label:'销售额',type:'money'},{key:'acos',label:'ACOS',type:'percent'},{key:'roas',label:'ROAS',type:'ratio'}]
function format(v:any,t:string,code=currency.value){return v==null?'—':t==='money'?money(v,code):t==='percent'?percent(v):t==='ratio'?Number(v).toFixed(2):number(v)}

const preferences=ref<Record<string,string[]>>({}),columnsOpen=ref(false),columnDraft=ref<string[]>([]),columnSearch=ref(''),columnsBusy=ref(false)
const quickField=ref('')
const inlineValues=ref<Record<string,Record<string,number>>>({}),campaignSettings=ref<any>(null),campaignBaseline=ref<any>({})
const strategyNames:Record<string,string>={LEGACY_FOR_SALES:'动态竞价－只降低',AUTO_FOR_SALES:'动态竞价－提高和降低',MANUAL:'固定竞价',RULE_BASED:'基于规则的竞价'}
const placementFields=[['placementTop','搜索结果顶部（首页）'],['placementRest','搜索结果的其余位置'],['placementProduct','商品页面'],['placementBusiness','亚马逊企业购']]
const widths=ref<Record<string,Record<string,number>>>({}),widthVersion=ref(0)
const width=(key:string,fallback:number)=>widths.value[currentLevel.value]?.[key]||fallback
async function loadPreferences(){const pid=profile.value;if(pid){const params=new URLSearchParams({profile_id:pid});const [p,w]=await Promise.all([api('/advertising/column-preferences?'+params),api('/advertising/column-widths?'+params)]);if(pid===profile.value){preferences.value=p;widths.value=w}}}
let widthSave=Promise.resolve()
function saveWidths(){const body={profile_id:profile.value,level:currentLevel.value,widths:{...(widths.value[currentLevel.value]||{})}};widthSave=widthSave.then(()=>api('/advertising/column-widths',body)).catch((e)=>{ElMessage.error('列宽保存失败：'+(e as Error).message)})}
function resizeColumn(w:number,_old:number,column:{columnKey:string}){if(!column.columnKey)return;widths.value[currentLevel.value]={...(widths.value[currentLevel.value]||{}),[column.columnKey]:Math.max(60,Math.min(1600,Math.round(w)))};saveWidths()}
function resetWidths(){widths.value[currentLevel.value]={};widthVersion.value++;saveWidths()}

function cycleSort(key:string){if(sort.value!==key){sort.value=key;direction.value='asc'}else if(direction.value==='asc')direction.value='desc';else{sort.value='';direction.value='desc'}search()}
function sortMark(key:string){return sort.value===key?(direction.value==='asc'?' ↑':' ↓'):' ↕'}
const fieldLabels:Record<string,string>={'extendedData.creationDateTime':'创建时间','extendedData.lastUpdateDateTime':'更新时间','extendedData.servingStatus':'投放状态','extendedData.servingStatusDetails':'投放状态详情',creationDate:'创建时间',lastUpdateDate:'更新时间',servingStatus:'投放状态',campaignId:'活动ID',adGroupId:'广告组ID',adId:'广告ID',keywordId:'关键词ID',targetId:'投放ID',portfolioId:'广告组合ID',startDate:'开始日期',endDate:'结束日期',targetingType:'投放类型',state:'设置状态',name:'名称',sku:'SKU',asin:'ASIN',expression:'投放表达式',expressionType:'表达式类型',resolvedExpression:'解析投放项',tags:'标签',globalCampaignId:'全局活动ID',marketplaceBudgetAllocation:'预算分配方式','budget.budget':'每日预算','budget.budgetType':'预算类型','dynamicBidding.strategy':'竞价策略','dynamicBidding.placementBidding':'展示位置加价','dynamicBidding.shopperCohortBidding':'受众加价','offAmazonSettings.offAmazonBudgetControlStrategy':'站外投放设置'}
function metricLabel(k:string){const m=k.match(/^(purchasesSameSku|purchases|unitsSoldClicks|unitsSoldSameSku|attributedSalesSameSku|sales|acosClicks|roasClicks)(\d+)d$/);if(m)return ({purchasesSameSku:'直接订单',purchases:'购买量',unitsSoldClicks:'销售件数',unitsSoldSameSku:'直接销售件数',attributedSalesSameSku:'直接销售额',sales:'销售额',acosClicks:'ACOS',roasClicks:'ROAS'} as any)[m[1]]+'（'+m[2]+'天归因）';return ({salesOtherSku7d:'其他商品销售额（7天）',unitsSoldOtherSku7d:'其他商品件数（7天）',addToList:'加入清单',qualifiedBorrows:'有效借阅',royaltyQualifiedBorrows:'版税有效借阅',kindleEditionNormalizedPagesRead14d:'Kindle阅读页数（14天）',kindleEditionNormalizedPagesRoyalties14d:'Kindle版税（14天）',cvr:'转化率'} as any)[k]||k}
const columnCatalog=computed(()=>{
 const l=currentLevel.value;const c:any[]=[];const add=(key:string,label:string,type='text',width=150,def=false)=>c.push({key,label,type,width,def})
 add('country','国家','text',100,!props.context&&!country.value);add('store','店铺')
 if(l!=='campaign'){add('campaign_name','广告活动','text',200,l==='ad');add('adgroup_name','广告组','text',180)}
 if(['campaign','adgroup','ad'].includes(l))add('targeting_type','活动类型','type',130,true)
 if(l==='campaign'){add('budget','每日预算','budget',180,true);add('top_share','首页首位展示份额','percent',170,true);add('top_adjustment','首页首位竞价调整','percent',170,true);add('start_date','开始日期');add('end_date','结束日期');add('bidding_strategy','竞价策略')}
 if(l==='adgroup'){add('default_bid','默认竞价','default_bid',180,true);add('counts','投放 / 商品','counts',120,true)}
 if(l==='ad'){add('identifiers','SKU / ASIN / FNSKU','identifiers',245,true);add('product_name','品名','text',180,true);add('available','可售库存','number',110,true);add('image','商品图片','image',90)}
 if(['target','negative','search'].includes(l))add('match_type','匹配类型','match',140,true)
 if(l==='target'){add('suggestion','建议竞价','suggestion',210,true);add('bid','竞价','bid',180,true);add('top_share','首页首位展示份额','percent',170)}
 if(l==='search')add('target','对应投放','text',180,true)
 if(l!=='negative'){
  for(const m of metricColumns)add(m.key,m.label,m.type,m.type==='money'?125:110,true)
  add('cvr','转化率','percent',120)
  for(const k of data.value.report_columns||[])if(/^(purchases|sales|attributedSales|unitsSold|acosClicks|roasClicks|addToList|qualifiedBorrows|royaltyQualifiedBorrows|kindleEdition)/.test(k))add(k,metricLabel(k),k.startsWith('acos')?'percent':k.startsWith('roas')?'ratio':/sales|royalties/i.test(k)?'money':'number',175)
 }
 for(const k of data.value.raw_columns||[])if(!['name','sku','asin','startDate','endDate','budget.budget','targetingType','dynamicBidding.strategy'].includes(k))add('raw:'+k,fieldLabels[k]||k,'raw',180)
 return c
})
const visibleColumns=computed(()=>{const keys=preferences.value[currentLevel.value];return keys?keys.map(k=>columnCatalog.value.find(c=>c.key===k)).filter(Boolean):columnCatalog.value.filter(c=>c.def)})
const filteredColumns=computed(()=>columnCatalog.value.filter(c=>(c.label+' '+c.key).toLowerCase().includes(columnSearch.value.toLowerCase())))
function openColumns(){columnDraft.value=visibleColumns.value.map(c=>c.key);columnSearch.value='';columnsOpen.value=true}
function moveColumn(i:number,step:number){const a=[...columnDraft.value];if(i+step<0||i+step>=a.length)return;[a[i],a[i+step]]=[a[i+step],a[i]];columnDraft.value=a}
async function saveColumns(){columnsBusy.value=true;try{await api('/advertising/column-preferences',{profile_id:profile.value,level:currentLevel.value,columns:columnDraft.value});preferences.value[currentLevel.value]=[...columnDraft.value];columnsOpen.value=false}catch(e){ElMessage.error((e as Error).message)}finally{columnsBusy.value=false}}
function inlineValue(row:any,key:string){return inlineValues.value[row.key]?.[key]??row[key]}
function changeInline(row:any,key:string,v:any){(inlineValues.value[row.key]??={})[key]=v}
function dirtyInline(row:any,key:string){return inlineValues.value[row.key]?.[key]!=null&&Math.round(Number(inlineValues.value[row.key][key])*100)!==Math.round(Number(row[key])*100)}
async function quickEdit(row:any,key:string,value:any){startEdit(row);quickField.value=key;if(row.kind==='campaign'){campaignBaseline.value={state:row.state,dailyBudget:row.budget};editForm.value={...campaignBaseline.value}}editForm.value[key]=value;await preview()}
async function startCampaign(row:any){startEdit(row);editBusy.value=true;try{const d=await api('/advertising/campaign-settings/'+encodeURIComponent(row.id)+'?'+new URLSearchParams({profile_id:row.profile_id||profile.value}));campaignSettings.value=d;campaignBaseline.value=structuredClone(d.values);editForm.value=structuredClone(d.values)}catch(e){editError.value=(e as Error).message}finally{editBusy.value=false}}
function audienceChange(id:string){editForm.value.audiences=id?[{shopperCohortType:'AUDIENCE_SEGMENT',percentage:0,audienceSegments:[{audienceId:id}]}]:[]}
function servingStatus(value:any):string{if(Array.isArray(value))return value.map(servingStatus).join('；');if(typeof value==='object')return Object.values(value).map(servingStatus).join('；');const code=String(value).replace(/_DETAIL$/,'');const names:Record<string,string>={AD_STATUS_LIVE:'投放中',TARGETING_CLAUSE_STATUS_LIVE:'投放中',AD_ELIGIBLE:'可投放',ELIGIBLE:'可投放',AD_INELIGIBLE:'不可投放',INELIGIBLE:'不可投放',OTHER:'其他状态',UNKNOWN:'未知状态',AD_CREATION_FAILED:'广告创建失败',AD_CREATION_OFFLINE_FAILED:'广告创建失败',AD_CREATION_OFFLINE_IN_PROGRESS:'广告创建中',AD_CREATION_OFFLINE_PENDING:'等待创建',PIR_RULE_EXCLUDED:'规则已排除',VARIATION_PARENT:'父体不可投放'};if(names[code])return names[code];const suffixes:Record<string,string>={OUT_OF_BUDGET:'预算不足',EXCEED_SPENDS_LIMIT:'超出花费限制',PAYMENT_FAILURE:'付款失败',PENDING_REVIEW:'待审核',PENDING_START_DATE:'未到开始日期',CREATIVE_REJECTED:'素材审核未通过',REJECTED:'审核未通过',POLICING_SUSPENDED:'投放受限',ARCHIVED:'已归档',PAUSED:'已暂停',STATUS_ENABLED:'已启用',INCOMPLETE:'资料不完整',LOW_BID:'竞价过低',ENDED:'已结束',OUT_OF_STOCK:'缺货',NO_INVENTORY:'缺货',NOT_BUYABLE:'商品不可购买',NOT_IN_BUYBOX:'未获得购物车',NO_PURCHASABLE_OFFER:'没有可购买报价',MISSING_IMAGE:'缺少图片',MISSING_DECORATION:'素材不完整',LANDING_PAGE_NOT_AVAILABLE:'落地页不可用',ADS_NOT_DELIVERING:'广告未投放',BLOCKED:'投放被阻止'};for(const [k,v] of Object.entries(suffixes))if(code===k||code.endsWith('_'+k))return v;return '其他投放状态'}
function cellText(row:any,col:any){let v=col.type==='raw'?row.raw_fields?.[col.key.slice(4)]:row.metrics&&col.key in row.metrics?row.metrics[col.key]:row[col.key];if(col.key==='product_name'&&!v)return '';if(v==null||v==='')return '—';if(col.key.toLowerCase().includes('servingstatus'))return servingStatus(v);if(col.key.endsWith('DateTime'))return time(v);if(col.type==='type')return v==='AUTO'?'自动投放':'手动投放';if(col.type==='match')return matchNames[v]||v;if(col.key==='bidding_strategy')return strategyNames[v]||v;if(['money','number','percent','ratio'].includes(col.type))return format(v,col.type,row.currency||currency.value);return typeof v==='object'?JSON.stringify(v):String(v)}
const chartMetric=ref('clicks'),chartRows=computed(()=>data.value.trends?.[currency.value]||data.value.trend||[])
const chartMax=computed(()=>Math.max(1,...chartRows.value.map((r:any)=>Number(r[chartMetric.value]||0))))
const acosMax=computed(()=>Math.max(100,...chartRows.value.map((r:any)=>Number(r.acos||0))))
function x(i:number){return 55+i*1090/Math.max(1,chartRows.value.length-1)}
function path(key:string,max:number){let result='',prev='';chartRows.value.forEach((r:any,i:number)=>{if(r[key]==null){prev='';return}const consecutive=prev&&new Date(r.date).getTime()-new Date(prev).getTime()===86400000;result+=(consecutive?' L':' M')+x(i)+','+(185-Number(r[key])/max*155);prev=r.date});return result}
function hoverChart(e:MouseEvent){const b=(e.currentTarget as SVGElement).getBoundingClientRect();hover.value=Math.max(0,Math.min(chartRows.value.length-1,Math.round(((e.clientX-b.left)/b.width*1200-55)/1090*Math.max(1,chartRows.value.length-1))))}
const draggedColumn=ref(''),dragOverColumn=ref('')
function dragColumn(event:DragEvent,key:string){draggedColumn.value=key;if(event.dataTransfer){event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',key)}}
function dropColumn(event:DragEvent,key:string){const from=draggedColumn.value;if(!from||from===key)return;const rect=(event.currentTarget as HTMLElement).getBoundingClientRect();const after=event.clientY>rect.top+rect.height/2;const items=columnDraft.value.filter(k=>k!==from);items.splice(items.indexOf(key)+(after?1:0),0,from);columnDraft.value=items;draggedColumn.value='';dragOverColumn.value=''}
const placementRows=computed(()=>data.value.rows.flatMap((r:any)=>{const raw=r.raw_fields?.['dynamicBidding.placementBidding'];const values=Array.isArray(raw)?raw:[];return [['PLACEMENT_TOP','搜索结果顶部（首页）'],['PLACEMENT_REST_OF_SEARCH','搜索结果其余位置'],['PLACEMENT_PRODUCT_PAGE','商品页面'],['PLACEMENT_AMAZON_BUSINESS','亚马逊企业购']].map(([key,label])=>({...r,placement:label,adjustment:values.find((v:any)=>v.placement===key)?.percentage??null}))}))
</script>
<template>
<AdsCreatePage v-if="createMode" :mode="createMode" :profile-id="profile" :profiles="profiles" :campaign="campaign" @close="createMode='';load()" @created="load"/>
<div v-else class="advertising-panel">
 <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
 <div v-if="campaign" class="ads-breadcrumb"><el-button link @click="emit('home')">{{store}}-{{country}}</el-button><el-icon><ArrowRight/></el-icon><el-button link class="breadcrumb-campaign" @click="openEntity('campaign',campaign)">广告活动：{{campaign.name}}</el-button><template v-if="group"><el-icon><ArrowRight/></el-icon><strong>广告组：{{group.name}}</strong></template></div>
 <nav class="ads-sections" aria-label="广告分类"><button v-for="[key,label] in sections" :key="key" :class="{selected:section===key}" :aria-pressed="section===key" @click="selectSection(key)">{{label}}</button></nav>
 <div class="ads-toolbar"><div><el-button v-if="canEditAds && ['campaign','adgroup'].includes(section)" type="primary" plain :disabled="!profile||(!props.context&&!country)||section==='adgroup'&&!campaign" @click="createMode=section">{{section==='campaign'?'创建广告活动':'创建广告组'}}</el-button><el-button @click="showJobs=true">同步记录</el-button><el-button :icon="Refresh" @click="load">刷新页面</el-button></div></div>
 <div v-if="active" class="ads-progress">正在同步资料与日报，完成后自动刷新，关闭页面不影响后台同步。</div>
 <section v-if="!['negative','logs'].includes(currentLevel)" class="panel performance">
  <div class="kpis"><div><span>ACOS</span><b>{{percent(summary?.acos)}}</b></div><div><span>点击</span><b>{{number(summary?.clicks)}}</b></div><div><span>广告订单</span><b>{{number(summary?.purchases)}}</b></div><div><span>CPC</span><b>{{money(summary?.cpc)}}</b></div><div><span>总花费</span><b>{{money(summary?.cost)}}</b></div></div>
  <div class="chart-toolbar"><strong>{{specialView?'活动整体表现走势':'表现走势'}}</strong><el-select v-if="data.currencies?.length>1" v-model="performanceCurrency" aria-label="走势币种" style="width:100px" :placeholder="currency"><el-option v-for="c in data.currencies" :key="c" :value="c" :label="c"/></el-select><el-radio-group v-model="chartMetric" size="small"><el-radio-button value="clicks">点击量</el-radio-button><el-radio-button value="cost">花费</el-radio-button><el-radio-button value="sales">销售额</el-radio-button></el-radio-group><span class="muted">蓝色：所选指标　绿色：ACOS（右轴）</span></div>
  <div class="chart" v-if="chartRows.length"><svg viewBox="0 0 1200 220" role="img" aria-label="广告每日表现走势" @mousemove="hoverChart" @mouseleave="hover=null"><g v-for="i in 4" :key="i"><line x1="55" x2="1145" :y1="30+(i-1)*155/3" :y2="30+(i-1)*155/3" stroke="#e5eeea" stroke-dasharray="3 5"/><text x="0" :y="34+(i-1)*155/3">{{(chartMax*(4-i)/3).toFixed(1)}}</text><text x="1150" :y="34+(i-1)*155/3">{{(acosMax*(4-i)/3).toFixed(0)}}%</text></g><path :d="path(chartMetric,chartMax)" stroke="#438df1" fill="none" stroke-width="2.5"/><path :d="path('acos',acosMax)" stroke="#75bc5a" fill="none" stroke-width="2.5"/><g v-for="(r,i) in chartRows" :key="r.date"><circle :cx="x(Number(i))" :cy="185-Number(r[chartMetric]||0)/chartMax*155" r="2" fill="#438df1"/></g><text x="55" y="212">{{chartRows[0].date}}</text><text x="1050" y="212">{{chartRows.at(-1).date}}</text><line v-if="hover!==null" :x1="x(hover)" :x2="x(hover)" y1="20" y2="190" stroke="#a5b8b1" stroke-dasharray="5"/></svg><div class="chart-tooltip" v-if="hover!==null&&chartRows[hover]"><b>{{chartRows[hover].date}}</b><span>点击 {{number(chartRows[hover].clicks)}}</span><span>花费 {{money(chartRows[hover].cost)}}</span><span>销售额 {{money(chartRows[hover].sales)}}</span><span>ACOS {{percent(chartRows[hover].acos)}}</span></div></div><div v-else class="chart-empty"></div>
 </section>
 <section class="panel results">
  <form class="ads-filters" @submit.prevent="search">
   <el-select v-model="store" :disabled="!!context" aria-label="店铺" placeholder="店铺" @change="accountChange"><el-option v-for="v in stores" :key="v" :value="v" :label="v"/></el-select>
   <el-select v-model="country" :disabled="!!context" clearable aria-label="国家" placeholder="全部国家" @change="accountChange"><el-option label="全部国家" value=""/><el-option v-for="v in countries" :key="v" :value="v" :label="(countryNames[v]||v)+' · '+v"/></el-select>
   <el-select v-model="searchType" aria-label="搜索类型"><el-option label="综合搜索" value="all"/><el-option label="SKU" value="sku"/><el-option label="ASIN" value="asin"/><el-option label="FNSKU" value="fnsku"/><el-option label="品名" value="product_name"/><el-option label="活动 / 广告组名称" value="name"/></el-select>
   <el-input v-model="q" :prefix-icon="Search" clearable placeholder="SKU / ASIN / FNSKU / 品名 / 活动或组名称" aria-label="广告搜索"/>
   <el-select v-model="preset" aria-label="时间范围" @change="choosePeriod"><el-option v-for="p in periodOptions" :key="p[0]" :value="p[0]" :label="p[1]"/></el-select>
   <el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" :shortcuts="shortcuts" start-placeholder="开始日期" end-placeholder="结束日期" range-separator="至" @change="preset='custom'"/>
   <el-select v-if="!['logs','search'].includes(currentLevel)" v-model="state" clearable placeholder="全部状态" aria-label="状态"><el-option v-for="(v,k) in states" :key="k" :label="v" :value="k"/></el-select><el-button native-type="submit" type="primary">查询</el-button>
  <el-button :disabled="!profile" @click="resetWidths">重置列宽</el-button></form>
  <div class="ads-notes"><span>{{data.timezone||'Europe/Paris'}} · 最近N天包含今天；今天数据尚未完整。7天点击归因。不同层级按各自报表展示，可能存在差异。</span><br><template v-if="!['negative','logs'].includes(currentLevel)"><span v-if="data.metrics_ready">已覆盖 {{data.coverage?.days}} / {{data.coverage?.expected}} 天（{{data.coverage?.start}} 至 {{data.coverage?.end}}）<b v-if="!data.coverage?.complete"> · 当前指标仅含已同步日期</b> · 更新 {{time(data.report_at)}}</span><span v-else>尚无所选日期的表现报表，请同步；未获取的指标显示 —。</span><br>长周期从本地历史汇总；超出亚马逊可查询时间的历史无法补取，缺失日期不计为零。</template><span v-if="!data.product_mapping_available"><br>尚未匹配到该店的商品资料；品名只使用明确关联或唯一旧编码，缺失数据留空。</span><span v-if="currentLevel==='ad'"><br>库存：英国单独取数；欧洲共享库存只取一份（德国优先），不累加各国重复库存。缺少本店库存快照时显示 —。</span><span v-if="currentLevel==='search'"><br>搜索词报表仅含产生点击的搜索词，曝光可能与广告活动报表不同。</span></div>
 <div class="panel-head"><h2>{{sections.find(([key])=>key===section)?.[1]}} <span class="count-badge">{{data.total||0}}</span></h2><div class="result-actions"><span class="muted resize-hint">拖动表头分隔线调整列宽</span><el-button v-if="canEditAds && currentLevel==='negative'" type="primary" @click="startNegative()">新增否定投放</el-button><el-button v-if="currentLevel!=='logs'&&!specialView" :disabled="!profile" @click="openColumns">自定义列</el-button></div></div>
 <template v-if="specialView">
 <el-table v-if="section==='placement'" :data="placementRows" border v-loading="loading"><el-table-column prop="name" label="广告活动" min-width="220"/><el-table-column prop="country" label="国家" width="90"/><el-table-column prop="placement" label="广告位" min-width="220"/><el-table-column label="竞价调整"><template #default="{row}">{{percent(row.adjustment)}}</template></el-table-column><el-table-column label="操作" width="120"><template #default="{row}"><el-button v-if="canEditAds" link @click="startCampaign(row)">编辑设置</el-button></template></el-table-column></el-table>
 <el-table v-else :data="data.rows" border v-loading="loading"><el-table-column prop="name" label="广告活动" min-width="220"/><el-table-column prop="country" label="国家" width="90"/><el-table-column label="状态"><template #default="{row}">{{states[row.state]}}</template></el-table-column><el-table-column label="竞价策略" min-width="200"><template #default="{row}">{{strategyNames[row.bidding_strategy]||row.bidding_strategy||'—'}}</template></el-table-column><el-table-column label="每日预算"><template #default="{row}">{{money(row.budget,row.currency)}}</template></el-table-column><el-table-column v-if="section==='settings'" prop="start_date" label="开始日期"/><el-table-column v-if="section==='settings'" prop="end_date" label="结束日期"/><el-table-column label="操作" width="120"><template #default="{row}"><el-button v-if="canEditAds" link @click="startCampaign(row)">编辑设置</el-button></template></el-table-column></el-table>
 </template>
 <el-table v-else-if="currentLevel==='logs'" border class="ads-table" @header-dragend="resizeColumn" :key="widthVersion" :data="data.rows" v-loading="loading"><el-table-column label="时间" column-key="created_at" :width="width('created_at',180)"><template #default="{row}">{{time(row.created_at)}}</template></el-table-column><el-table-column prop="actor" label="操作人" column-key="actor" :width="width('actor',100)"/><el-table-column prop="name" label="对象" column-key="name" :width="width('name',220)"/><el-table-column label="修改内容" column-key="changes" :width="width('changes',300)"><template #default="{row}"><div v-for="(v,k) in row.changes" :key="k">{{fieldNames[String(k)]||k}}：{{fieldValue(String(k),row.before[k])}} → {{fieldValue(String(k),v)}}</div></template></el-table-column><el-table-column label="结果" column-key="status" :width="width('status',135)"><template #default="{row}">{{statusNames[row.status]||row.status}}</template></el-table-column><el-table-column prop="error" label="说明" column-key="error" :width="width('error',220)"/></el-table>
 <el-table v-else border @header-dragend="resizeColumn" :data="data.rows" v-loading="loading" row-key="key" class="ads-table" :key="widthVersion+currentLevel+visibleColumns.map(c=>c.key).join(',')">
  <el-table-column v-if="currentLevel!=='search'" column-key="state" label="开关" :width="width('state',80)" fixed><template #default="{row}"><el-tooltip :content="states[row.state]||row.state"><el-switch :model-value="row.state==='ENABLED'" :disabled="!canEditAds||row.state==='ARCHIVED'||editBusy" :aria-label="'开启或暂停 '+row.name" @change="(v:any)=>quickEdit(row,'state',v?'ENABLED':'PAUSED')"/></el-tooltip></template></el-table-column>
  <el-table-column v-if="currentLevel!=='ad'" column-key="name" :width="width('name',250)" fixed><template #header><button class="sort-head" @click="cycleSort('name')">{{currentLevel==='search'?'用户搜索词':currentLevel==='negative'?'否定关键词 / 商品':currentLevel==='target'?'投放项':labels[currentLevel]+'名称'}}{{sortMark('name')}}</button></template><template #default="{row}"><div class="name-cell"><el-button v-if="['campaign','adgroup'].includes(currentLevel)" link type="primary" @click="drill(row)">{{row.name}}</el-button><strong v-else>{{row.name}}</strong><el-button v-if="canEditAds && currentLevel==='campaign'" link :icon="EditPen" :aria-label="'编辑活动 '+row.name" :disabled="!canEditAds||row.state==='ARCHIVED'||editBusy" @click.stop="startCampaign(row)"/></div><div v-if="currentLevel!=='search'" class="cell-sub">ID {{row.id}}</div></template></el-table-column>
  <el-table-column v-for="col in visibleColumns" :key="col.key" :column-key="col.key" :width="width(col.key,col.width)" :align="['money','number','percent','ratio'].includes(col.type)?'right':'left'"><template #header><button v-if="!['image','suggestion','counts','identifiers'].includes(col.type)" class="sort-head" :aria-label="col.label+'排序'" @click="cycleSort(col.key)">{{col.label}}{{sortMark(col.key)}}</button><span v-else>{{col.label}}</span><div v-if="col.type==='suggestion'" class="suggest-header"><span>平日</span><el-button link :icon="Refresh" aria-label="刷新建议竞价" :loading="suggestLoading" @click.stop="refreshSuggestions"/></div></template><template #default="{row}">
   <div v-if="['budget','default_bid','bid'].includes(col.type)" class="inline-price"><el-input-number :model-value="inlineValue(row,col.key)" @update:model-value="(v:any)=>changeInline(row,col.key,v)" :min="0.01" :precision="2" :step="0.01" controls-position="right" :disabled="!canEditAds||row.state==='ARCHIVED'" :aria-label="col.label+' '+row.name"/><el-button v-if="canEditAds && dirtyInline(row,col.key)" link type="success" :icon="Check" :disabled="editBusy" :aria-label="'保存'+col.label+' '+row.name" @click="quickEdit(row,col.key==='budget'?'dailyBudget':col.key==='default_bid'?'defaultBid':'bid',inlineValue(row,col.key))">保存</el-button></div>
   <div v-else-if="col.type==='suggestion'" class="bid-suggestion"><template v-if="row.suggestion"><el-tooltip :content="'更新于 '+time(row.suggestion.fetched_at)"><span>{{Number(row.suggestion.mid).toFixed(2)}} <span class="muted">({{Number(row.suggestion.low).toFixed(2)}}–{{Number(row.suggestion.high).toFixed(2)}})</span></span></el-tooltip><el-dropdown trigger="click" @command="(key:string)=>applySuggestion(row,key)" :disabled="!canEditAds||row.state==='ARCHIVED'"><el-button size="small" :disabled="!canEditAds||row.state==='ARCHIVED'">应用⌄</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-for="(label,key) in {mid:'建议',low:'最低',high:'最高'}" :key="key" :command="key">{{label}}：{{money(row.suggestion[key],row.currency)}}</el-dropdown-item></el-dropdown-menu></template></el-dropdown></template><span v-else class="muted">—</span></div>
   <span v-else-if="col.type==='counts'">{{row.target_count}} / {{row.product_count}}</span>
   <template v-else-if="col.type==='identifiers'">{{row.sku||'—'}}<div class="cell-sub">{{row.asin||'—'}}</div><div class="cell-sub">{{row.fnsku||'—'}}</div></template>
   <el-image v-else-if="col.type==='image'&&row.image" :src="row.image" fit="contain" style="width:48px;height:48px"/>
   <span v-else :title="cellText(row,col)">{{cellText(row,col)}}</span>
  </template></el-table-column>
  <el-table-column v-if="canEditAds && currentLevel==='search'" column-key="actions" label="操作" :width="width('actions',115)" fixed="right"><template #default="{row}"><el-button link type="primary" @click="startNegative(row)">添加否定</el-button></template></el-table-column>
  <template #empty><el-empty :description="currentLevel==='search'&&!data.metrics_ready?'尚未同步该时段的搜索词报表':'没有匹配的记录'"/></template>
 </el-table>
 <div v-if="summary" class="ads-totals"><b>{{data.coverage?.complete?'筛选结果合计':'已同步部分合计'}}</b><span>曝光 {{number(summary.impressions)}}</span><span>点击 {{number(summary.clicks)}}</span><span>花费 {{money(summary.cost)}}</span><span>销售额 {{money(summary.sales)}}</span><span>ACOS {{percent(summary.acos)}}</span></div>
 <div class="table-footer"><AppPagination v-model:current-page="page" :total="data.total||0" @change="load" v-model:page-size="pageSize"/></div></section>
 <p v-if="!canEditAds" class="ads-footer muted">当前账号可查看和同步已授权店铺的广告数据；创建广告、调价及启停由管理员操作。</p>
 <p class="ads-footer muted">当前显示所选店铺站点的商品推广数据。广告状态为设置状态，实际投放还受活动、广告组、预算及资格影响。修改需预览确认，操作日志记录本系统提交的修改。</p>
 <el-dialog v-model="editOpen" :title="isCreate?'新增否定投放':'编辑广告设置'" :width="editKind==='campaign'?'760px':'620px'" top="6vh" :close-on-click-modal="false" :close-on-press-escape="!editBusy" :show-close="!editBusy"><p><b>{{editRow?.name}}</b> · {{editRow?.store||store}} / {{editRow?.country||country}}</p><el-alert v-if="editError" :title="editError" type="error" :closable="false" show-icon/>
 <template v-if="!previewData"><el-form label-position="top" class="edit-form"><template v-if="isCreate"><el-form-item label="否定类型"><el-radio-group v-model="editKind"><el-radio-button value="negative_keyword">否定关键词</el-radio-button><el-radio-button value="negative_target">否定商品</el-radio-button></el-radio-group></el-form-item><template v-if="editKind==='negative_keyword'"><el-form-item label="否定关键词"><el-input v-model="editForm.keywordText" maxlength="250"/></el-form-item><el-form-item label="否定方式"><el-select v-model="editForm.matchType"><el-option label="否定精准" value="NEGATIVE_EXACT"/><el-option label="否定词组" value="NEGATIVE_PHRASE"/></el-select></el-form-item></template><el-form-item v-else label="商品ASIN"><el-input v-model="editForm.asin" maxlength="10"/></el-form-item></template><template v-else-if="editKind==='campaign'"><template v-if="campaignSettings">
 <el-alert v-for="w in campaignSettings.warnings" :key="w" :title="w" type="warning" :closable="false"/>
 <el-form-item label="活动名称"><el-input v-model="editForm.name" maxlength="250"/></el-form-item>
 <el-form-item label="状态"><el-radio-group v-model="editForm.state"><el-radio value="ENABLED">开启</el-radio><el-radio value="PAUSED">暂停</el-radio></el-radio-group></el-form-item>
 <el-form-item label="广告组合"><el-select v-model="editForm.portfolioId" filterable clearable @clear="editForm.portfolioId=null" placeholder="未设置广告组合"><el-option v-for="v in campaignSettings.portfolios" :key="v.portfolioId" :value="String(v.portfolioId)" :label="v.name"/></el-select></el-form-item>
 <el-form-item :label="'每日预算（'+editCurrency+'）'"><el-input-number v-model="editForm.dailyBudget" :min="0.01" :precision="2"/></el-form-item>
 <div class="campaign-dates"><el-form-item label="开始日期"><el-input :model-value="campaignSettings.startDate" disabled/></el-form-item><el-form-item label="结束日期"><el-date-picker v-model="editForm.endDate" type="date" value-format="YYYY-MM-DD" placeholder="无结束日期" clearable/></el-form-item></div>
 <el-form-item label="投放类型">{{campaignSettings.targetingType==='AUTO'?'自动投放':'手动投放'}}</el-form-item>
 <el-form-item label="广告活动竞价策略"><el-radio-group v-model="editForm.biddingStrategy" class="strategy-options"><el-radio v-for="(v,k) in strategyNames" :key="k" :value="k" :disabled="k==='RULE_BASED'&&campaignBaseline.biddingStrategy!=='RULE_BASED'">{{v}}</el-radio></el-radio-group><small class="muted">基于规则的竞价需先在亚马逊配置规则；已有设置会保留。</small></el-form-item>
 <el-form-item v-for="p in placementFields" :key="p[0]" :label="p[1]+'加价（%）'"><el-input-number v-model="editForm[p[0]]" :min="0" :max="900" :precision="0" :disabled="campaignSettings.restricted&&p[0]==='placementBusiness'"/></el-form-item>
 <el-form-item label="受众加价"><el-select :model-value="editForm.audiences?.[0]?.audienceSegments?.[0]?.audienceId||''" clearable filterable :disabled="campaignSettings.restricted" placeholder="不对受众提价" @change="audienceChange"><el-option v-for="a in campaignSettings.audiences" :key="a.audienceId" :value="a.audienceId" :label="a.audienceResolved||a.audienceId"/><el-option v-if="editForm.audiences?.[0]&&!campaignSettings.audiences.some((a:any)=>a.audienceId===editForm.audiences[0].audienceSegments[0].audienceId)" :value="editForm.audiences[0].audienceSegments[0].audienceId" label="当前受众（保留已有设置）"/></el-select><el-input-number v-if="editForm.audiences?.[0]" v-model="editForm.audiences[0].percentage" :min="0" :max="900" :precision="0" :disabled="campaignSettings.restricted"/><span v-if="editForm.audiences?.[0]">%</span></el-form-item>
 <el-form-item label="站外投放设置"><el-radio-group v-model="editForm.offAmazonStrategy" :disabled="campaignSettings.restricted"><el-radio value="MAXIMIZE_REACH">扩大受众触达</el-radio><el-radio value="MINIMIZE_SPEND">限制站外花费</el-radio></el-radio-group></el-form-item>
 <el-form-item label="备注（保存在本地）"><el-input v-model="editForm.note" type="textarea" :rows="3" maxlength="500" show-word-limit/></el-form-item>
 </template><template v-else-if="quickField"><el-form-item v-if="quickField==='dailyBudget'" :label="'每日预算（'+editCurrency+'）'"><el-input-number v-model="editForm.dailyBudget" :min="0.01" :precision="2"/></el-form-item><el-form-item v-else label="状态"><el-radio-group v-model="editForm.state"><el-radio value="ENABLED">开启</el-radio><el-radio value="PAUSED">暂停</el-radio></el-radio-group></el-form-item></template><p v-else>{{editBusy?'正在读取最新活动设置…':'可返回列表重新打开活动设置。'}}</p></template><template v-else><el-form-item v-if="editKind==='adgroup'" label="广告组名称"><el-input v-model="editForm.name" maxlength="250"/></el-form-item><el-form-item label="状态"><el-radio-group v-model="editForm.state"><el-radio value="ENABLED">开启</el-radio><el-radio value="PAUSED">暂停</el-radio></el-radio-group></el-form-item><el-form-item v-if="['keyword','target'].includes(editKind)" :label="'竞价（'+editCurrency+'）'"><el-input-number v-model="editForm.bid" :min="0.01" :max="10000" :precision="2" :step="0.01"/></el-form-item><el-form-item v-if="editKind==='adgroup'" :label="'默认竞价（'+editCurrency+'）'"><el-input-number v-model="editForm.defaultBid" :min="0.01" :max="10000" :precision="2" :step="0.01"/></el-form-item></template></el-form></template>
 <template v-else><p class="preview-notice">请确认以下修改（备注仅保存在本地，其余提交亚马逊）：</p><template v-if="true"><TableReset table-key="AdvertisingPanel/table-3"/><el-table border data-width-key="AdvertisingPanel/table-3" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-3', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-3', column, event)" :data="Object.entries(previewData.changes).map(([key,value])=>({key,before:previewData.before[key],after:value}))"><el-table-column :column-key="'column-1'" :width="tableWidths.width('table-3', 'column-1', undefined)" label="属性"><template #default="{row}">{{fieldNames[row.key]||row.key}}</template></el-table-column><el-table-column :column-key="'column-2'" :width="tableWidths.width('table-3', 'column-2', undefined)" label="修改前"><template #default="{row}">{{fieldValue(row.key,row.before)}}</template></el-table-column><el-table-column :column-key="'column-3'" :width="tableWidths.width('table-3', 'column-3', undefined)" label="修改后"><template #default="{row}">{{fieldValue(row.key,row.after)}}</template></el-table-column></el-table></template></template>
 <template #footer><el-button :disabled="editBusy" @click="previewData?previewData=null:editOpen=false">{{previewData?'返回编辑':'取消'}}</el-button><el-button type="primary" :loading="editBusy" @click="previewData?confirm():preview()">{{previewData?'确认并提交亚马逊':'提交预览'}}</el-button></template></el-dialog>
 <el-dialog v-model="columnsOpen" :title="labels[currentLevel]+' · 自定义列'" width="850px"><p class="muted">开关固定在最前面，广告页使用 SKU 识别商品。勾选显示列，右侧拖动排序或点击 × 移除；设置随账号保存。未获取的数据显示 —。</p><el-input v-model="columnSearch" placeholder="搜索列名称" clearable/><div class="column-picker"><el-checkbox-group v-model="columnDraft"><el-checkbox v-for="c in filteredColumns" :key="c.key" :value="c.key">{{c.label}}</el-checkbox></el-checkbox-group><div class="selected-columns"><b>已选 {{columnDraft.length}} 列</b><div v-for="(key,i) in columnDraft" :key="key" draggable="true" :data-column="key" :class="{'drag-over':dragOverColumn===key}" @dragstart="dragColumn($event,key)" @dragover.prevent="dragOverColumn=key" @drop.prevent="dropColumn($event,key)" @dragend="draggedColumn='';dragOverColumn=''"><span class="drag-handle" title="拖动调整顺序">⠿</span><span>{{columnCatalog.find(c=>c.key===key)?.label||key}}</span><el-button link :disabled="i===0" @click="moveColumn(i,-1)" :aria-label="'上移 '+key">↑</el-button><el-button link :disabled="i===columnDraft.length-1" @click="moveColumn(i,1)" :aria-label="'下移 '+key">↓</el-button><el-button link class="remove-column" :aria-label="'移除 '+(columnCatalog.find(c=>c.key===key)?.label||key)" @click="columnDraft=columnDraft.filter(k=>k!==key)">×</el-button></div></div></div><template #footer><el-button @click="columnDraft=columnCatalog.filter(c=>c.def).map(c=>c.key)">恢复默认列</el-button><el-button @click="columnsOpen=false">取消</el-button><el-button type="primary" :loading="columnsBusy" @click="saveColumns">保存列设置</el-button></template></el-dialog>
 <el-dialog v-model="showJobs" title="广告同步记录" width="920px"><template v-if="true"><TableReset table-key="AdvertisingPanel/table-4"/><el-table border data-width-key="AdvertisingPanel/table-4" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-4', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-4', column, event)" :data="jobs"><el-table-column :column-key="'column-1'" label="范围" :width="tableWidths.width('table-4', 'column-1', '220')"><template #default="{row}">{{row.start_date}} 至 {{row.end_date}}</template></el-table-column><el-table-column :column-key="'column-2'" label="状态" :width="tableWidths.width('table-4', 'column-2', '170')"><template #default="{row}">{{jobStates[row.status]||row.status}}</template></el-table-column><el-table-column :column-key="'column-3'" :width="tableWidths.width('table-4', 'column-3', undefined)" label="报表" min-width="230"><template #default="{row}">{{Object.entries(row.reports).map(([k,v]:any)=>(labels[k.split(':')[0]]||k)+': '+v.status).join('；')}}</template></el-table-column><el-table-column :column-key="'error'" :width="tableWidths.width('table-4', 'error', undefined)" prop="error" label="说明" min-width="250"/></el-table></template><template #footer><el-button @click="showJobs=false">关闭</el-button></template></el-dialog>

</div>
